const first=(...xs)=>{for(const x of xs){if(x!==null&&x!==undefined&&String(x).trim())return String(x).trim()}return''};
function details(order){const raw=order?.details;if(!raw)return{};if(typeof raw==='object')return raw;try{return JSON.parse(raw)}catch{return{}}}
function items(order){const d=details(order);if(Array.isArray(d.items)&&d.items.length)return d.items;return[{store_id:first(d.store_id,'legacy'),store_name:first(d.store_name,'المتجر'),product_name:d.product_name||order?.product_name||order?.name||'المنتج',product_image:d.product_image||order?.image_url||'',selected_options:{color:d.color||'',size:d.size||'',volume:d.volume||''},quantity:Number(d.quantity??order?.quantity??1)||1,unit_price_local:Number(d.unit_price_local??order?._unit_price??order?.total_price??0)||0,line_total_local:Number(order?.total_price??0)||0,currency:order?.currency||d.local_currency||'IQD'}]}
function storeGroups(order){const d=details(order),map=new Map();for(const x of items(order)){const id=first(x.store_id,d.store_id,'legacy'),name=first(x.store_name,(Array.isArray(d.stores)?d.stores.find(s=>String(s.store_id)===String(id))?.store_name:''),d.store_name,'المتجر');if(!map.has(id))map.set(id,{store_id:id,store_name:name,items:[],quantity:0,subtotal_local:0,currency:x.currency||d.local_currency||order?.currency||'IQD'});const g=map.get(id),q=Math.max(1,Number(x.quantity)||1),line=Number(x.line_total_local)||((Number(x.unit_price_local)||0)*q);g.items.push(x);g.quantity+=q;g.subtotal_local+=line}if(Array.isArray(d.stores)){for(const s of d.stores){const g=map.get(String(s.store_id));if(g){g.store_name=first(s.store_name,g.store_name);if(Number.isFinite(Number(s.subtotal_local)))g.subtotal_local=Number(s.subtotal_local)}}}return[...map.values()]}
