function customerData(order){const d=details(order),c=order?._kintoCustomer||((d.customer&&typeof d.customer==='object')?d.customer:{});return{name:first(c.name,order?.customer_name,d.customer_name),code:first(c.customer_code,c.code,c.customerCode,order?._customer_code,order?.customer_code,d.customer_code),phone:first(c.phone,order?._customer_phone,order?.customer_phone,d.customer_phone),secondary:first(c.secondary_phone,c.phone2,c.alt_phone,order?._secondary_phone,order?.secondary_phone,d.secondary_phone,d.customer_secondary_phone),country:first(c.country,c.country_name,order?.country,d.country,d.customer_country),province:first(c.province,c.governorate,c.state,c.city,order?.province,order?.governorate,order?.state,order?.city,d.province,d.governorate,d.state,d.city,d.customer_province,d.customer_governorate),address:first(c.address,c.address_details,c.full_address,c.delivery_address,order?.address,order?.address_details,order?.delivery_address,d.address,d.address_details,d.full_address,d.delivery_address,d.customer_address)}}
async function hydrateCustomer(order){if(!order?.customer_id||order._kintoCustomerLoaded)return order?._kintoCustomer||null;order._kintoCustomerLoaded=true;try{const r=await fetch(`${SUPABASE_URL}/rest/v1/customers?select=*&id=eq.${encodeURIComponent(order.customer_id)}&limit=1`,{cache:'no-store',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,Accept:'application/json'}});if(r.ok){const rows=await r.json();order._kintoCustomer=Array.isArray(rows)?rows[0]||null:null}}catch(e){console.warn('KINTO customer hydration failed',e)}return order._kintoCustomer||null}
