function safeUrl(v){const s=String(v||'').trim();if(!s)return'';try{const u=new URL(s,location.href);return['http:','https:','mailto:','tel:'].includes(u.protocol)?u.href:''}catch{return''}}
function digits(v){return String(v||'').replace(/[^0-9]/g,'')}
function contactItems(settings){const out=[],phone=first(settings.support_phone),email=first(settings.support_email),wa=first(settings.whatsapp_url),address=first(settings.contact_address);if(phone)out.push({label:'الدعم',value:phone,href:`tel:${digits(phone)||phone}`});if(phone)out.push({label:'WhatsApp',value:phone,href:safeUrl(wa)||(digits(phone)?`https://wa.me/${digits(phone).replace(/^00/,'')}`:'')});if(email)out.push({label:'Email',value:email,href:`mailto:${email}`});if(address)out.push({label:'العنوان',value:address,href:''});return out}
