function globalTotals(order){const d=details(order),goods=Number(d.customer_total_local??order?.total_price??0)||0,external=Number(order?.external_shipping_fee??d.external_shipping_fee??d.shipping_fee??0)||0,delivery=Number(order?.delivery_fee??d.delivery_fee??d.local_delivery_fee??0)||0;return{goods,external,delivery,grand:goods+external+delivery,currency:order?.currency||d.local_currency||'IQD'}}
