function bundleHtml(order){const groups=storeGroups(order),t=globalTotals(order),id=`kv94-${Math.random().toString(36).slice(2,9)}`,tabs=groups.map((g,i)=>`<button type="button" class="kinto-v94-tab ${i===0?'active':''}" data-v94-target="${id}-${i}">${esc(g.store_name)}</button>`).join(''),panels=groups.map((g,i)=>`<section id="${id}-${i}" class="kinto-v94-panel ${i===0?'active':''}"><div class="kinto-v94-store-head"><b>${esc(g.store_name)}</b><strong dir="ltr">${money(g.subtotal_local,g.currency||t.currency)}</strong></div><div class="kinto-v94-items">${g.items.map((x,j)=>itemCard(x,j,g.currency||t.currency)).join('')}</div></section>`).join('');return `<section class="kinto-v94-bundle" data-v94-tabs><div class="kinto-v94-global"><span>الإجمالي العالمي للطلب</span><strong dir="ltr">${money(t.goods,t.currency)}</strong></div>${groups.length>1?`<nav class="kinto-v94-tabs">${tabs}</nav>`:''}${panels}</section>`}
function normalizeCode(order){const raw=first(order?.order_code,details(order).bundle_id);const m=raw.match(/^KN-([0-9]+)$/i);return m?`KN-${m[1].padStart(6,'0')}`:raw||'---'}
function englishDate(value){if(!value)return'---';const x=new Date(value);if(Number.isNaN(x.getTime()))return'---';return new Intl.DateTimeFormat('en-GB',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,numberingSystem:'latn'}).format(x).replace(',','')}
function invoiceRows(group){return group.items.map((x,i)=>{const q=Math.max(1,Number(x.quantity)||1),u=Number(x.unit_price_local)||0,l=Number(x.line_total_local)||u*q,o=x.selected_options||{},cur=x.currency||group.currency;return `<tr><td>${i+1}</td><td>${x.product_image?`<img src="${esc(x.product_image)}">`:''}</td><td class="product-cell"><b>${esc(x.product_name||'المنتج')}</b><small>${[o.color&&'اللون: '+o.color,o.size&&'المقاس: '+o.size,o.volume&&'الحجم: '+o.volume].filter(Boolean).map(esc).join(' · ')}</small></td><td>${q}</td><td dir="ltr">${money(u,cur)}</td><td dir="ltr">${money(l,cur)}</td></tr>`}).join('')}
async function invoice(order){await hydrateCustomer(order);const settings=await loadSiteSettings(),groups=storeGroups(order),t=globalTotals(order),c=customerData(order),code=normalizeCode(order),date=englishDate(order?.created_at||details(order).submitted_at),tabs=groups.map((g,i)=>`<button class="tab ${i===0?'active':''}" onclick="showStore(${i},this)">${esc(g.store_name)}</button>`).join(''),sections=groups.map((g,i)=>`<section class="store-section ${i===0?'active':''}" data-store-section="${i}"><div class="store-total"><span>مجموع ${esc(g.store_name)}</span><b dir="ltr">${money(g.subtotal_local,g.currency||t.currency)}</b></div><table><thead><tr><th>#</th><th>الصورة</th><th>المنتج / الخيارات</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${invoiceRows(g)}</tbody></table></section>`).join(''),footer=contactsHtml(settings),w=window.open('','_blank','width=1000,height=800');if(!w)return alert('يرجى السماح بالنوافذ المنبثقة لطباعة الفاتورة.');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>KINTO Invoice ${esc(code)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial;color:#13231d;margin:0}.invoice{max-width:190mm;margin:auto}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #ff7a00;padding-bottom:12px}.brand{font-size:28px;font-weight:900;color:#063b2d}.code{text-align:center}.global-total{margin:14px 0;padding:12px;border:2px solid #063b2d;border-radius:10px;display:flex;justify-content:space-between;font-size:16px;font-weight:900}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.tab{border:1px solid #d5ddd9;background:#fff;padding:8px 12px;border-radius:999px;font-weight:800;cursor:pointer}.tab.active{background:#063b2d;color:#fff}.store-section{display:none}.store-section.active{display:block}.store-total{display:flex;justify-content:space-between;padding:9px;background:#fff8ec;border:1px solid #f1cf9c;border-radius:8px;margin-bottom:8px;font-weight:900}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border-bottom:1px solid #dbe5e0;padding:7px;text-align:center;font-size:11px}th{background:#063b2d;color:#fff}td img{width:42px;height:42px;object-fit:contain}.product-cell{text-align:right}.product-cell small{display:block;color:#64748b;margin-top:3px}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:16px}.card{border:1px solid #dbe5e0;border-radius:10px;padding:10px;font-size:10px}.card div{padding:3px 0}.totals div{display:flex;justify-content:space-between;padding:6px;border-bottom:1px solid #eee}.totals .grand{font-size:14px;border-top:2px solid #ff7a00;font-weight:900}.footer-contacts{margin-top:22px;border-top:1px solid #ccd6d1;padding-top:8px;text-align:center;font-size:8px;color:#52625c}.footer-contacts a{color:inherit;text-decoration:none}.actions{text-align:center;margin:18px}.actions button{background:#063b2d;color:#fff;border:0;border-radius:8px;padding:10px 16px;font-weight:900}@media print{.actions,.tabs{display:none!important}.store-section{display:block!important;page-break-inside:avoid;margin-bottom:10mm}}</style><script>function showStore(i,b){document.querySelectorAll('.store-section').forEach((s,n)=>s.classList.toggle('active',n===i));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}<\/script></head><body><main class="invoice"><header class="head"><div class="brand">KINTO</div><div class="code"><b>${esc(code)}</b><div>${esc(date)}</div></div><div>${esc(order?.status||'---')}</div></header><div class="global-total"><span>الإجمالي العالمي المطلوب من العميل</span><b dir="ltr">${money(t.grand,t.currency)}</b></div>${groups.length>1?`<nav class="tabs">${tabs}</nav>`:''}${sections}<section class="bottom"><div class="card"><b>معلومات العميل</b><div>الاسم: ${esc(c.name||'---')}</div><div>كود العميل: ${esc(c.code||'---')}</div><div>الهاتف: ${esc(c.phone||'---')}</div><div>الهاتف الاحتياطي: ${esc(c.secondary||'---')}</div><div>الدولة: ${esc(c.country||'---')}</div><div>المحافظة: ${esc(c.province||'---')}</div><div>العنوان: ${esc(c.address||'---')}</div></div><div class="card totals"><div><span>مجموع السلع</span><b dir="ltr">${money(t.goods,t.currency)}</b></div><div><span>الشحن الخارجي (يدوي)</span><b dir="ltr">${money(t.external,t.currency)}</b></div><div><span>التوصيل الداخلي (يدوي)</span><b dir="ltr">${money(t.delivery,t.currency)}</b></div><div class="grand"><span>الإجمالي</span><b dir="ltr">${money(t.grand,t.currency)}</b></div></div></section>${footer}<div class="actions"><button onclick="print()">تحميل / طباعة الفاتورة PDF</button></div></main></body></html>`);w.document.close();return w}
function repairNativeDetails(container,order){if(!container)return;[...container.querySelectorAll('.detail-box,div,p,li')].forEach(el=>{const txt=(el.textContent||'').trim();if(/^سعر القطعة\s*:/i.test(txt))el.remove()})}
