document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v94-target]');if(!b)return;const root=b.closest('[data-v94-tabs]');if(!root)return;root.querySelectorAll('.kinto-v94-tab').forEach(x=>x.classList.remove('active'));root.querySelectorAll('.kinto-v94-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');root.querySelector('#'+CSS.escape(b.dataset.v94Target))?.classList.add('active')});
const style=document.createElement('style');style.textContent='.kinto-v94-bundle{margin-top:16px;border-top:1px solid rgba(148,163,184,.25);padding-top:12px}.kinto-v94-global,.kinto-v94-store-head{display:flex;justify-content:space-between;gap:12px;align-items:center;border:1px solid rgba(245,196,81,.28);border-radius:10px;padding:10px;margin-bottom:10px}.kinto-v94-global{font-weight:900;background:rgba(245,196,81,.08)}.kinto-v94-tabs{display:flex;gap:7px;flex-wrap:wrap;margin:8px 0 12px}.kinto-v94-tab{border:1px solid rgba(148,163,184,.3);background:transparent;color:inherit;border-radius:999px;padding:7px 11px;font-weight:800;cursor:pointer}.kinto-v94-tab.active{background:#063b2d;color:#fff;border-color:#ff7a00}.kinto-v94-panel{display:none}.kinto-v94-panel.active{display:block}.kinto-v94-items{display:grid;gap:9px}.kinto-v94-item{display:grid;grid-template-columns:64px minmax(0,1fr);gap:10px;align-items:center;border:1px solid rgba(148,163,184,.22);border-radius:10px;padding:9px}.kinto-v94-item img{width:64px;height:64px;object-fit:contain;border-radius:8px}.kinto-v94-meta,.kinto-v94-price{font-size:12px;opacity:.82;margin-top:4px}';document.head.appendChild(style);
